definition.script:
pipeline {
    agent any

    environment {
        UPSTREAM_JOB   = 'VCFLoader - Batch File Generator'
        DOWNSTREAM_JOB = 'ETL - NewVCFLoader by chromosome v4.1'
        ARTIFACT_NAME  = 'vcf_indexes_batch.txt'
    }

    stages {
        stage('Stage 1: Build & Fetch Index Batch File') {
            steps {
                script {
                    echo "Triggering ${env.UPSTREAM_JOB}..."

                    def upstreamRun = build job: env.UPSTREAM_JOB, wait: true

                    copyArtifacts projectName: env.UPSTREAM_JOB,
                                  selector: specific(upstreamRun.getNumber().toString()),
                                  filter: env.ARTIFACT_NAME

                    echo "Successfully retrieved artifact from ${env.UPSTREAM_JOB}."
                }
            }
        }

        stage('Stage 2: Run ETL Loader') {
            steps {
                script {
                    // Read file and split into a list of lines, filtering out empty lines
                    def lines = readFile(file: env.ARTIFACT_NAME).split('\r?\n').findAll { !it.trim().isEmpty() }

                    echo "Found ${lines.size()} lines to process."

                    // Loop through each line and trigger the downstream job
                    for (int i = 0; i < lines.size(); i++) {
                        def currentLine = lines[i].trim()
                        echo "Processing line ${i + 1}/${lines.size()}: ${currentLine}"

                        build job: env.DOWNSTREAM_JOB, 
                              wait: true,
                              parameters: [
                                  string(name: 'vcfIndex', value: currentLine)
                              ]
                    }
                }
            }
        }
    }
}
